var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

public record Order(string? Sku, int Quantity, decimal UnitPrice);

app.MapPost("/orders", async (Order order) =>
{
    // Validate sku: nonblank (required, must not be empty or whitespace-only)
    if (string.IsNullOrWhiteSpace(order.Sku))
    {
        return Results.BadRequest(new { error = "sku is required and must not be blank" });
    }

    // Validate quantity: 1..100 inclusive
    if (order.Quantity < 1 || order.Quantity > 100)
    {
        return Results.BadRequest(new { error = "quantity must be between 1 and 100 inclusive" });
    }

    // Validate unitPrice: >= 0
    if (order.UnitPrice < 0)
    {
        return Results.BadRequest(new { error = "unitPrice must be >= 0" });
    }

    // Calculate total and return 201 Created
    var total = order.Quantity * order.UnitPrice;
    var result = new { total = total };
    return Results.StatusCode(201, result);
});

app.Run();

